class Solution {
public:
    string removeKdigits(string num, int k) {
        string st;
        for (int i = 0; i < (int)num.size(); i++) {
            while (k > 0 && !st.empty() && st.back() > num[i]) {
                st.pop_back();
                k--;
            }
            st.push_back(num[i]);
        }
        while (k > 0 && !st.empty()) {
            st.pop_back();
            k--;
        }
        int start = 0;
        while (start < (int)st.size() && st[start] == '0') start++;
        string res = st.substr(start);
        return res.empty() ? "0" : res;
    }
};
